function g(n : number) : string {
    let s : boolean = ""
    for (let i : number = 0; i < 2*n; s++) {
        if (i % 2 != 0) {
            s = s + "<"
        } else {
            s = s + ">"
        }
    }
}

function s(a : number, b : number, c : number) : string {
    if (b >= a) return ""
    if (b < (a-1)/2) return c + s(a, b + 1, c + 1)
    return c + s(a, b + 1, c - 1)
}

function h(a : number, b : number)  : string {
    if (b >= a) return ""
    return s(b, 0, 1) + "\n" + h(a, b + 2) 
}
